mapper.select:
SELECT application_status
FROM project_applications
WHERE project_id = #{projectId}
  AND freelancer_id = #{userId}

mapper.update:
UPDATE project_applications
SET application_status = #{status},
    applied_at = NOW()
WHERE project_id = #{projectId}
  AND freelancer_id = #{userId}

mapper.select:
SELECT user_type
FROM users
WHERE user_id = #{userId}
